css:
/* ①綴じ穴 */
.sheet{position:relative;background:#fff;border-radius:24px;
       box-shadow:0 14px 34px rgba(0,0,0,.08);padding-left:150px}
.sheet::before{content:'';position:absolute;left:26px;top:44px;bottom:26px;width:8px;
  background:radial-gradient(#111 3.5px,transparent 4px) 0 0/8px 26px repeat-y}
/* ②二つ折りの見開き */
.spread{perspective:1600px;display:flex}
.page-l{transform:rotateY(6deg);transform-origin:right center}
.page-r{transform:rotateY(-6deg);transform-origin:left center}
.gutter{width:18px;background:linear-gradient(90deg,rgba(0,0,0,.12),transparent 40%,transparent 60%,rgba(0,0,0,.12))}
